#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

static Node *insert_front(Node *head, int val) {
    Node *n = (Node *)malloc(sizeof(Node));
    n->data = val;
    n->next = head;
    return n;
}

static Node *insert_back(Node *head, int val) {
    Node *n = (Node *)malloc(sizeof(Node));
    n->data = val;
    n->next = NULL;
    if (!head) return n;
    Node *curr = head;
    while (curr->next) curr = curr->next;
    curr->next = n;
    return head;
}

static Node *delete_val(Node *head, int val) {
    if (!head) return NULL;
    if (head->data == val) {
        Node *tmp = head->next;
        free(head);
        return tmp;
    }
    Node *curr = head;
    while (curr->next && curr->next->data != val) {
        curr = curr->next;
    }
    if (curr->next) {
        Node *target = curr->next;
        curr->next = target->next;
        free(target);
    }
    return head;
}

static void print_list(const Node *head) {
    if (!head) {
        printf("EMPTY\n");
        return;
    }
    const Node *curr = head;
    while (curr) {
        printf("%d%s", curr->data, curr->next ? " " : "\n");
        curr = curr->next;
    }
}

static void free_all(Node *head) {
    while (head) {
        Node *tmp = head->next;
        free(head);
        head = tmp;
    }
}

int main(void) {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    Node *head = NULL;
    for (int i = 0; i < q; i++) {
        char cmd[20];
        if (scanf("%s", cmd) != 1) break;
        if (strcmp(cmd, "INSERT_FRONT") == 0) {
            int v;
            scanf("%d", &v);
            head = insert_front(head, v);
        } else if (strcmp(cmd, "INSERT_BACK") == 0) {
            int v;
            scanf("%d", &v);
            head = insert_back(head, v);
        } else if (strcmp(cmd, "DELETE") == 0) {
            int v;
            scanf("%d", &v);
            head = delete_val(head, v);
        } else if (strcmp(cmd, "PRINT") == 0) {
            print_list(head);
        }
    }
    free_all(head);
    return 0;
}

