#include <string.h>

typedef struct {
    int is_allocated;
    int is_freed;
    int value;
} Slot;

typedef struct {
    char name[16];
    int slot_id;
} Alias;

static Slot slots[100];
static Alias aliases[1000];
static int alias_count = 0;

static int find_alias(const char *name) {
    for (int i = 0; i < alias_count; i++) {
        if (strcmp(aliases[i].name, name) == 0) return i;
    }
    return -1;
}

int main(void) {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    for (int i = 0; i < 100; i++) {
        slots[i].is_allocated = 0;
        slots[i].is_freed = 0;
    }
    for (int k = 0; k < q; k++) {
        char cmd[16];
        if (scanf("%s", cmd) != 1) break;
        if (strcmp(cmd, "ALLOC") == 0) {
            int id, val;
            scanf("%d %d", &id, &val);
            slots[id].is_allocated = 1;
            slots[id].is_freed = 0;
            slots[id].value = val;
        } else if (strcmp(cmd, "ALIAS") == 0) {
            char name[16];
            int id;
            scanf("%s %d", name, &id);
            int idx = find_alias(name);
            if (idx == -1) {
                strcpy(aliases[alias_count].name, name);
                aliases[alias_count].slot_id = id;
                alias_count++;
            } else {
                aliases[idx].slot_id = id;
            }
        } else if (strcmp(cmd, "FREE") == 0) {
            int id;
            scanf("%d", &id);
            slots[id].is_allocated = 0;
            slots[id].is_freed = 1;
        } else if (strcmp(cmd, "DEREF") == 0) {
            char name[16];
            scanf("%s", name);
            int idx = find_alias(name);
            if (idx == -1) {
                printf("NULL POINTER\n");
            } else {
                int id = aliases[idx].slot_id;
                if (slots[id].is_freed) {
                    printf("DANGLING POINTER DETECTED\n");
                } else if (slots[id].is_allocated) {
                    printf("%d\n", slots[id].value);
                } else {
                    printf("NULL POINTER\n");
                }
            }
        }
    }
    return 0;
}

