#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Room {
    char name[32];
    struct Room *up;
    struct Room *down;
    struct Room *left;
    struct Room *right;
} Room;

static Room *find_room(Room *rooms, int n, const char *name) {
    if (strcmp(name, "NONE") == 0) return NULL;
    for (int i = 0; i < n; i++) {
        if (strcmp(rooms[i].name, name) == 0) return &rooms[i];
    }
    return NULL;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Room *rooms = (Room *)malloc(n * sizeof(Room));
    char up_names[100][32], down_names[100][32], left_names[100][32], right_names[100][32];
    for (int i = 0; i < n; i++) {
        scanf("%s %s %s %s %s", rooms[i].name, up_names[i], down_names[i], left_names[i], right_names[i]);
        rooms[i].up = rooms[i].down = rooms[i].left = rooms[i].right = NULL;
    }
    // Link pointers
    for (int i = 0; i < n; i++) {
        rooms[i].up = find_room(rooms, n, up_names[i]);
        rooms[i].down = find_room(rooms, n, down_names[i]);
        rooms[i].left = find_room(rooms, n, left_names[i]);
        rooms[i].right = find_room(rooms, n, right_names[i]);
    }
    char start_name[32];
    scanf("%s", start_name);
    Room *current = find_room(rooms, n, start_name);
    int m;
    if (scanf("%d", &m) != 1) { free(rooms); return 0; }
    for (int i = 0; i < m; i++) {
        char dir[4];
        scanf("%s", dir);
        Room *next = NULL;
        if (dir[0] == 'U') next = current->up;
        else if (dir[0] == 'D') next = current->down;
        else if (dir[0] == 'L') next = current->left;
        else if (dir[0] == 'R') next = current->right;
        if (next != NULL) {
            current = next;
        }
        printf("%s%c", current->name, (i == m - 1) ? '\n' : ' ');
    }
    printf("Final: %s\n", current->name);
    free(rooms);
    return 0;
}
